function count = compute_output(plaza)
count = 0;
[a, b] = size(plaza);
for j = 1:b
      count = count + (plaza(a,j) > 0);
end



clear_boundary.m

function plaza = clear_boundary(input)
plaza = input;
[a,b] = size(plaza);
for i = 1:b
   if plaza(a,i) > 0
      plaza(a,i) = 0;
   end
end



